// 递归拒重复字段，空初态条件和真实已配置条件严格区分；来源真实性由入战冷读再验。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "military_combat_conditions_codec.hpp"
#include "military_combat_conditions.hpp"
#include "military_officer_codec.hpp"
#include "resident/domains/conditions/domain_codec_util.hpp"
#include "resident/storage/common_checkpoint.hpp"
namespace hanmo::resident::military_combat_conditions_codec {
namespace {
using namespace domain_codec;
Status wire(const MilitaryCombatConditionState& s){MilitaryBattleRecord b;b.id="condition_wire";b.created_tick=s.entry_tick;for(const auto& row:s.units){BattleUnit u;u.unit_id=row.unit_id;b.units.push_back(u);}return validate_military_combat_condition_shape(b,s);}
Status emit_row(ProjectionWriter& w,const MilitaryCombatConditionSnapshot& r){w.field("unit_id",r.unit_id);w.field("source_garrison_id",r.source_garrison_id);w.field("last_condition_fact_id",r.last_condition_fact_id);w.field("efficiency_bp",r.efficiency_bp);if(r.training)w.field("training",*r.training);if(r.fatigue)w.field("fatigue",*r.fatigue);w.order_fields(r.field_order);return w.status();}
void dec(const V& v,MilitaryCombatConditionSnapshot& r){const StableId p="combat_conditions/units";boundary::fields(v,{"unit_id","source_garrison_id","last_condition_fact_id","efficiency_bp"},{"training","fatigue"},p);r.field_order=boundary::order(v);r.unit_id=boundary::get_string(v,"unit_id",p);r.source_garrison_id=boundary::get_string(v,"source_garrison_id",p);r.last_condition_fact_id=boundary::get_string(v,"last_condition_fact_id",p);r.efficiency_bp=boundary::get_int(v,"efficiency_bp",p);if(const auto* x=v.find("training"))r.training=boundary::integer(*x,p+"/training");if(const auto* x=v.find("fatigue"))r.fatigue=boundary::integer(*x,p+"/fatigue");}
Status walk(CodecVisitor& c,MilitaryCombatConditionSnapshot& r){c.field("unit_id",r.unit_id);c.field("source_garrison_id",r.source_garrison_id);c.field("last_condition_fact_id",r.last_condition_fact_id);c.field("efficiency_bp",r.efficiency_bp);c.optional("training",r.training,[](auto& child,auto& v){return domain_codec::visit(child,v);});c.optional("fatigue",r.fatigue,[](auto& child,auto& v){return domain_codec::visit(child,v);});common_checkpoint::strings(c,"field_order",r.field_order);return c.status();}
}
Status emit_fields(ProjectionWriter& w,const MilitaryCombatConditionState& s){auto checked=wire(s);if(!checked.ok)return checked;w.field("entry_tick",s.entry_tick);w.sequence("units",s.units,[](auto& c,const auto& r){return c.object("",[&](auto& row){return emit_row(row,r);});});w.order_fields(s.field_order);return w.status();}
BoundaryValue encode(const MilitaryCombatConditionState& s){BoundaryValue out;BoundaryProjectionWriter sink(out);auto checked=sink.object("",[&](auto& w){return emit_fields(w,s);});if(checked.ok)checked=sink.finish();if(!checked.ok)boundary::fail(checked.error.original.code,checked.error.original.path);return out;}
Outcome<MilitaryCombatConditionState> decode(const BoundaryValue& v){try{auto unique=military_officer_codec::validate_json_unique_keys(v);if(!unique.ok)return {false,{},unique.error};boundary::fields(v,{"entry_tick","units"},{},"combat_conditions");MilitaryCombatConditionState s;s.field_order=boundary::order(v);s.entry_tick=boundary::get_int(v,"entry_tick","combat_conditions");for(const auto& item:boundary::array(boundary::field(v,"units","combat_conditions"),"units")){MilitaryCombatConditionSnapshot row;dec(item,row);s.units.push_back(std::move(row));}auto valid=wire(s);return valid.ok?Outcome<MilitaryCombatConditionState>{true,std::move(s),{}}:Outcome<MilitaryCombatConditionState>{false,{},valid.error};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status visit(CodecVisitor& c,MilitaryCombatConditionState& s){if(!(c.schema_features&military_combat_conditions_checkpoint_feature)||!(c.schema_features&military_garrison_rest_checkpoint_feature))return c.reject("MilitaryCombatConditionPrerequisiteRequired");c.field("entry_tick",s.entry_tick);c.sequence("units",s.units,[](auto& child,auto& row){return walk(child,row);});common_checkpoint::strings(c,"field_order",s.field_order);if(!c.status().ok)return c.status();auto valid=wire(s);return valid.ok?c.status():c.reject(valid.error.original.code,valid.error.original.path);}
}
